import * as THREE from 'three/webgpu';
import { texture, uv, vec4, uniform, mix } from 'three/tsl';
import gsap from 'gsap';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'journal-card-2-label';
  group.position.set(0, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const width = 1.6;
  const height = 0.4;

  const geometry = new THREE.PlaneGeometry(width, height);
  const map = ctx.textureLoader.load('/prism-mock/home/nodes/feature-card.png');
  map.colorSpace = THREE.SRGBColorSpace;

  const hoverLift = uniform(0);
  const uvNode = uv();
  const colorNode = texture(map, uvNode);
  const accentColor = vec4(1.0, 0.165, 0.22, 1.0);
  const mixed = mix(colorNode, accentColor, hoverLift.mul(0.08));

  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });
  material.colorNode = mixed;

  const plane = new THREE.Mesh(geometry, material);
  plane.name = 'journal-card-2-label-plane';
  group.add(plane);

  const textMesh = createTextMesh({
    text: 'Journal 2',
    fontAtlas: ctx.fontAtlas,
    font: 'display',
    weight: 400,
    size: 0.34 * (39 / 39),
    color: '#16161d',
    align: 'center',
    anchor: 'middle',
  });
  textMesh.position.set(0, 0, 0.01);
  group.add(textMesh);

  ctx.primitives['parallax-scroll'](group, { intensity: 0.25, trigger: 'scroll' });

  let hoverTween = null;
  let pressTween = null;
  const baseY = group.position.y;
  const baseZ = group.position.z;
  const baseScale = group.scale.x;

  const onHoverStart = () => {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.timeline()
      .to(group.position, { y: baseY + 0.15, duration: 0.7, ease: 'power3.out' }, 0)
      .to(hoverLift, { value: 1, duration: 0.7, ease: 'power3.out' }, 0);
  };

  const onHoverEnd = () => {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.timeline()
      .to(group.position, { y: baseY, duration: 0.5, ease: 'power2.out' }, 0)
      .to(hoverLift, { value: 0, duration: 0.5, ease: 'power2.out' }, 0);
  };

  const onClick = () => {
    if (pressTween) pressTween.kill();
    pressTween = gsap.timeline()
      .to(group.scale, { x: baseScale * 0.97, y: baseScale * 0.97, z: baseScale * 0.97, duration: 0.12, ease: 'back.out' })
      .to(group.scale, { x: baseScale, y: baseScale, z: baseScale, duration: 0.2, ease: 'back.out' });

    if (group.userData.emit) {
      group.userData.emit('hub-journal.select', { id: 'hub-journal-card-1' });
    }
  };

  group.userData.handlers = {
    onHoverStart,
    onHoverEnd,
    onClick,
  };

  group.userData.cleanup = () => {
    if (hoverTween) hoverTween.kill();
    if (pressTween) pressTween.kill();
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
    if (textMesh.geometry) textMesh.geometry.dispose();
    if (textMesh.material) textMesh.material.dispose();
  };

  return group;
}
